metadata.query:
// Log records of one lab service in a window, grouped by severity.
fetch logs, from:"2026-09-19T08:23:32.405Z", to:"2026-09-19T08:23:36.615Z"
| filter service.namespace == "easytrade-otel-lab" and service.name == "credit-card-order-service"
| summarize records = count(), with_trace = countIf(isNotNull(trace_id)), by: {loglevel, status}
| sort records desc
